def run(args):
    if not args or args[0] in ('-h', '--help', 'help'):
        sys.stdout.write('Operations with the Taplo config file\n\nUsage: taplo config [OPTIONS] <COMMAND>\n\nCommands:\n  default  Print the default `.taplo.toml` configuration file\n  schema   Print the JSON schema of the `.taplo.toml` configuration file\n  help     Print this message and the help of the given subcommand(s)\n')
        return 0
    cmd = args[0]
    if cmd == 'default':
