import sys, json, tomllib, datetime

def encode(v):
    if isinstance(v, dict): return {k: encode(x) for k,x in v.items()}
    if isinstance(v, list): return [encode(x) for x in v]
    if isinstance(v, bool): return {'type':'bool','value':str(v).lower()}
    if isinstance(v, int): return {'type':'integer','value':str(v)}
    if isinstance(v, float):
        s=repr(v)
        if s.endswith('.0'): s=s[:-2]
        return {'type':'float','value':s}
    if isinstance(v, (datetime.datetime,datetime.date,datetime.time)):
        return {'type':'datetime','value':json.dumps(v.isoformat().replace('+00:00','Z'))}
    if isinstance(v, str): return {'type':'string','value':v}
    return v

def run():
    try:
